  /* Phones: calm while the page is moving. The moving parts inside a drawing (tails,
     fins, blades, the fish in the wreck) cannot be handed to the graphics chip: the page
     redraws them itself on every frame, and on a slow phone that was a third of the work
     of a scroll frame. So while the page is being scrolled they hold their pose, together
     with the slow loops of the light (rays, glitter, snow), and they carry on from where
     they were 180 ms after the last movement. Swimming and bobbing never stop. Two class
     flips per gesture, on the layers concerned only (styles: css/styles.css 18.7). */
  var calmState = { on: false, timer: 0, nodes: null };
  function calmSet(on) {
    var n = calmState.nodes, i;
    if (!n) n = calmState.nodes = [life.layer, ocean.host].concat(all('.wreck-scene, .seabed')).filter(Boolean);
    calmState.on = on;
    for (i = 0; i < n.length; i++) n[i].classList.toggle('is-calm', on);
  }
  function calmEnd() { calmState.timer = 0; calmSet(false); }
  function calm() {
    if (!calmState.on) calmSet(true);
    win.clearTimeout(calmState.timer);
    calmState.timer = win.setTimeout(calmEnd, 180);
  }

  /* ---------------------------------------------------------------------
     4  Water and light, inside #ocean
     --------------------------------------------------------------------- */
  var ocean = { host: null, bubbles: null, torch: null, flags: {} };

  function wavePath(period, amp, base) {
    /* a closed band from above the top edge down to a sine-like lower edge */
    var d = 'M0 -12H1200V' + base, x = 1200, up = true, half = period / 2;
    while (x > 0) {
      d += 'Q' + (x - half / 2) + ' ' + (base + (up ? -amp : amp)) + ' ' + (x - half) + ' ' + base;
      x -= half;
      up = !up;
    }
    return d + 'Z';
  }

  function buildOcean() {
    var host = doc.getElementById('ocean');
    if (!host) return;
    ocean.host = host;
    host.textContent = '';
    var small = state.small, rand = rng(7919), i, n, html;

    make('div', 'ocean__water', host);

    /* sun rays: a few flat, hard-edged beams that sway and breathe */
    var rays = make('div', 'ocean__rays', host);
    var rayDefs = [
      [-6, 17, 15, 0.30, 9.5], [10, 24, 13, 0.38, 12], [29, 14, 16, 0.26, 8],
      [45, 27, 12, 0.34, 13.5], [66, 18, 14, 0.28, 10.5], [83, 22, 11, 0.32, 11.5]
    ];
    html = '';
    for (i = 0; i < rayDefs.length; i++) {
      if (small && i % 2) continue;
      html += '<i class="ocean__ray" style="--x:' + rayDefs[i][0] + '%;--w:' + (small ? rayDefs[i][1] * 1.7 : rayDefs[i][1]) +
        'vw;--tilt:' + rayDefs[i][2] + 'deg;--a:' + rayDefs[i][3] + ';--dur:' + rayDefs[i][4] + 's;--delay:-' + r1(rand() * 9) + 's"></i>';
    }
    rays.innerHTML = html;

    /* the water surface seen from below: two rippling bands */
    var surface = make('div', 'ocean__surface', host);
    surface.innerHTML =
      '<svg class="ocean__wave ocean__wave--b" viewBox="0 0 1200 60" preserveAspectRatio="none" focusable="false"><path d="' + wavePath(600, 9, 44) + '"/></svg>' +
      '<svg class="ocean__wave ocean__wave--a" viewBox="0 0 1200 60" preserveAspectRatio="none" focusable="false"><path d="' + wavePath(300, 6, 26) + '"/></svg>';

    /* sunlight glitter near the surface */
    var glitter = make('div', 'ocean__glitter', host);
    n = small ? 9 : 18;
    html = '';
    for (i = 0; i < n; i++) {
      html += '<i class="ocean__fleck" style="left:' + r1(3 + rand() * 94) + '%;top:' + r1(9 + rand() * 34) + '%;width:' +
        Math.round(7 + rand() * 13) + 'px;--dur:' + r1(2.2 + rand() * 2.6) + 's;--delay:-' + r1(rand() * 5) + 's"></i>';
    }
    glitter.innerHTML = html;

    /* marine snow: three tiled layers of specks, each falling by exactly one tile per loop */
    var snow = make('div', 'ocean__snow', host);
    snow.innerHTML = '<i class="ocean__flakes ocean__flakes--1"></i><i class="ocean__flakes ocean__flakes--2"></i><i class="ocean__flakes ocean__flakes--3"></i>';

    make('div', 'ocean__vignette', host);
    ocean.torch = make('div', 'ocean__torch', host);
    ocean.bubbles = make('div', 'ocean__bubbles', host);
    ocean.flags = {};
  }

  /* Pause the light layers that are fully faded at this depth (class flips only
     when a threshold is crossed, never per frame). */
  function oceanUpdate(p) {
    var host = ocean.host;
    if (!host) return;
    var f = ocean.flags, v;
    v = p > SUN_GONE;
    if (v !== f.noSun) { f.noSun = v; host.classList.toggle('ocean--no-sun', v); }
    v = p < SNOW_FROM;
    if (v !== f.noSnow) { f.noSnow = v; host.classList.toggle('ocean--no-snow', v); }
  }

  /* ---------------------------------------------------------------------
     5  Depth HUD: <nav class="depth-hud" aria-label="Depth gauge">
     --------------------------------------------------------------------- */
  var hud = { nav: null, nums: [], names: [], btns: [], toggle: null, open: false, targets: [], hasSections: false, flag: 0 };

  function buildHud() {
    var nav = make('nav', 'depth-hud');
    nav.setAttribute('aria-label', 'Depth gauge');
    var rows = ZONES.map(function (z, i) {
      /* the label starts with the visible text ("Shallow reef 5 m") and adds where the zone ends */
      return '<li><button type="button" class="depth-hud__btn" data-hud-zone="' + i + '" aria-label="' + z.name + ' ' + z.from + ' m to ' + z.to + ' m">' +
        '<span class="depth-hud__name">' + z.name + '</span> <span class="depth-hud__m">' + z.from + '<small> m</small></span></button></li>';
    }).join('');
    var reading = '<span class="depth-hud__num" data-hud-num>0</span><span class="depth-hud__unit"> m</span> <span class="depth-hud__zone" data-hud-name>' + ZONES[0].name + '</span>';
    nav.innerHTML =
      '<p class="depth-hud__read"><span class="visually-hidden">Current depth: </span>' + reading + '</p>' +
      '<button type="button" class="depth-hud__toggle" aria-expanded="false" aria-controls="depth-hud-zones">' + reading +
        '<span class="visually-hidden">. Show the depth zones</span>' +
        '<svg class="depth-hud__chev" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m6 14.5 6-6 6 6"/></svg></button>' +
      '<div class="depth-hud__panel" id="depth-hud-zones"><div class="depth-hud__rows">' +
        '<span class="depth-hud__track" aria-hidden="true"><span class="depth-hud__fill"></span><span class="depth-hud__dot"></span></span>' +
        '<ul class="depth-hud__list">' + rows + '</ul></div></div>';
    doc.body.appendChild(nav);

    hud.nav = nav;
    hud.nums = all('[data-hud-num]', nav);
    hud.names = all('[data-hud-name]', nav);
    hud.btns = all('[data-hud-zone]', nav);
    hud.toggle = nav.querySelector('.depth-hud__toggle');

    nav.addEventListener('click', function (e) {
      var btn = e.target.closest ? e.target.closest('[data-hud-zone]') : null;
      if (btn) {
        goToZone(parseInt(btn.getAttribute('data-hud-zone'), 10));
        if (hud.open) { hudOpen(false); hud.toggle.focus(); }
        return;
      }
      if (hud.toggle.contains(e.target)) hudOpen(!hud.open);
    });
    nav.addEventListener('keydown', function (e) {
      if ((e.key === 'Escape' || e.key === 'Esc') && hud.open) {
        e.stopPropagation();
        hudOpen(false);
        hud.toggle.focus();
      }
    });
    doc.addEventListener('pointerdown', function (e) {
      if (hud.open && !nav.contains(e.target)) hudOpen(false);
    }, { passive: true });

    /* compact gauge: the zone name that slides out on hover / focus can be put away
       with Escape (also when only the mouse is over it, hence the document listener);
       it comes back once the pointer or the focus has left the button */
    doc.addEventListener('keydown', function (e) {
      if ((e.key === 'Escape' || e.key === 'Esc') && !hud.open && !root.classList.contains('menu-open') &&
          ((nav.matches && nav.matches(':hover')) || nav.contains(doc.activeElement))) nav.classList.add('is-tip-off');
    });
    nav.addEventListener('mouseout', function (e) {
      var btn = e.target.closest ? e.target.closest('.depth-hud__btn') : null;
      if (btn && !btn.contains(e.relatedTarget)) nav.classList.remove('is-tip-off');
    });
    nav.addEventListener('focusout', function () { nav.classList.remove('is-tip-off'); });
  }

