    var w = filterWarp;
    if (!w || w.freed < 2) return null;
    var under = headerEl ? headerEl.offsetHeight : 0, max = state.maxScroll, full = max + w.freed;
    var a = w.top - under, b = w.bottom - under;
    if (a < 40 || b < a + 40 || max < b + 40) return null;
