  var CAST = {
    surface: [
      { art: 'turtle', kind: 'swim', w: 230, speed: 24, bob: 12, bobDur: 5.6, tilt: 2, par: 0.08 },
      { art: 'bream', kind: 'shoal', n: [6, 9], w: 60, speed: 42, bob: 6, bobDur: 3.4, par: -0.06 },
      { art: 'bream', kind: 'shoal', n: [5, 6], w: 46, speed: 33, bob: 5, bobDur: 3.9, par: 0.16 }
    ],
    reef: [
      { art: 'parrotfish', kind: 'swim', w: 150, speed: 36, bob: 9, bobDur: 4.4, tilt: 1.5, par: 0.05 },
      { art: 'seagrass', kind: 'grass', w: 150, par: 0.03 },
      { art: 'octopus', kind: 'anchor', w: 215, grass: true, par: 0.03 },
      { art: 'wrasse', kind: 'swim', dart: true, w: 104, speed: 60, bob: 6, bobDur: 2.8, par: -0.08 },
      { art: 'seagrass', kind: 'grass', w: 118, par: 0.03 },
      { art: 'wrasse', kind: 'swim', dart: true, w: 84, speed: 52, bob: 5, bobDur: 3.1, par: 0.14 }
    ],
    caves: [
      { art: 'moray', kind: 'anchor', side: 'left', w: 270, par: 0.03 },
      { art: 'jellyfish', kind: 'drift', w: 86, par: -0.06 },
      { art: 'grouper', kind: 'swim', w: 205, speed: 19, bob: 7, bobDur: 6.2, tilt: 1, par: 0.05 },
      { art: 'lionfish', kind: 'swim', w: 150, speed: 13, bob: 11, bobDur: 5.2, tilt: 2, par: -0.07 },
      { art: 'jellyfish', kind: 'drift', w: 62, par: 0.15 }
    ],
    blue: [
      /* solo: nothing else shares its water. glass: what a lane pays for passing behind panels (default 14) */
      { art: 'sunfish', kind: 'swim', w: 400, speed: 15, bob: 14, bobDur: 7.5, tilt: 1.2, par: 0.06, phase: 0.13, forward: true, solo: true, glass: 40 },
      { art: 'barracuda', kind: 'shoal', n: [5, 8], w: 165, speed: 58, bob: 4, bobDur: 3.2, par: -0.05 },
      { art: 'amberjack', kind: 'swim', w: 190, speed: 82, bob: 6, bobDur: 3.4, par: 0.1 },
      { art: 'amberjack', kind: 'swim', w: 140, speed: 66, bob: 5, bobDur: 3.8, par: 0.2 }
    ],
    wreck: [
      { art: 'grouper', kind: 'swim', dark: true, w: 215, speed: 14, bob: 6, bobDur: 7, par: 0.08 },
      { art: 'bream', kind: 'shoal', dark: true, n: [4, 6], w: 52, speed: 24, bob: 5, bobDur: 4.6, par: 0.04 },
      { art: 'grouper', kind: 'swim', dark: true, w: 150, speed: 11, bob: 5, bobDur: 8, par: 0.18 }
    ]
  };
  /* loose formation for shoals, in units of the group box (leader on the right) */
  var FORMATION = [[0.66, 0.44], [0.4, 0.18], [0.38, 0.7], [0.14, 0.42], [0.9, 0.2], [0.88, 0.72], [0.62, 0.92], [0.1, 0.06], [0.06, 0.82]];
