    var wreckEl = doc.querySelector('.wreck-scene');
    if (wreckEl) {
      var wr = wreckEl.getBoundingClientRect();
      var wsvg = wreckEl.querySelector('svg');                 // phones: the block is taller than the drawing (the tour)
      var wh = wsvg ? Math.min(wr.height, wsvg.getBoundingClientRect().height) : wr.height;
      if (wr.height > 2) bottomLimit = Math.min(bottomLimit, wr.bottom + sy - wh * 0.78);
    }

