        out += '<div class="sl ' + (still ? 'sl--still' : 'sl--drift is-off') + '" style="left:' + Math.round(spot.x) + 'px;top:' + Math.round(spot.y) + 'px;width:' + w +
          'px;height:' + h + 'px;' + (still ? '' : depthVars(spot.y, h, spot.par)) + '"><div class="sl__x" style="left:' + (dx < 0 ? -dx : 0) + 'px;top:' + dy +
          'px;width:' + size.w + 'px;height:' + size.h + 'px;--dx:' + dx + 'px;--dy:' + (-dy) + 'px;--dur:' + r1(20 + rand() * 12) + 's;--delay:-' + r1(rand() * 20 + age) + 's">' +
          ART[spec.art] + '</div></div>';
